import type { Category } from '@/domain/models/category'
import type { TransactionRecord } from '@/domain/models/transaction'
import { groupStartOf, isWithin, localDateKey, rangeBounds, type TransactionRange } from './date-range'

export interface MoneySummary {
  incomeCents: number
  expenseCents: number
  balanceCents: number
}

export interface CategoryTotal {
  categoryId: string
  name: string
  icon: string
  amountCents: number
  ratio: number
}

export interface TrendPoint extends MoneySummary {
  key: string
  label: string
}

export interface DashboardStats {
  day: MoneySummary
  month: MoneySummary
  year: MoneySummary
  monthDailyTrend: TrendPoint[]
  monthExpenseCategories: CategoryTotal[]
}

export interface ReportStats extends MoneySummary {
  trend: TrendPoint[]
  incomeCategories: CategoryTotal[]
  expenseCategories: CategoryTotal[]
}

export function summarize(records: readonly TransactionRecord[]): MoneySummary {
  let incomeCents = 0
  let expenseCents = 0
  for (const record of records) {
    if (record.type === 'income') incomeCents += record.amountCents
    else expenseCents += record.amountCents
  }
  return { incomeCents, expenseCents, balanceCents: incomeCents - expenseCents }
}

function categoryTotals(records: readonly TransactionRecord[], categories: readonly Category[], type: 'income' | 'expense'): CategoryTotal[] {
  const names = new Map(categories.map((category) => [category.id, category]))
  const totals = new Map<string, number>()
  for (const record of records) {
    if (record.type !== type) continue
    totals.set(record.categoryId, (totals.get(record.categoryId) ?? 0) + record.amountCents)
  }
  const total = [...totals.values()].reduce((sum, value) => sum + value, 0)
  return [...totals.entries()]
    .map(([categoryId, amountCents]) => {
      const category = names.get(categoryId)
      return {
        categoryId,
        name: category?.name ?? '未分类',
        icon: category?.icon ?? '❓',
        amountCents,
        ratio: total === 0 ? 0 : amountCents / total,
      }
    })
    .sort((a, b) => b.amountCents - a.amountCents)
}

/**
 * 按一级分类聚合二级分类的金额（首页专用）。每行展示父分类名 + 父图标 + 父 color（调用方自行取色）；
 * ratio 分母是整个周期内的总支出，等于 categoryTotals 中相同 type 的合计。
 * 没有 parentId 的孤立分类（数据脏）跳过。
 */
export function groupTotalsByParent(records: readonly TransactionRecord[], categories: readonly Category[], type: 'income' | 'expense'): CategoryTotal[] {
  const byId = new Map(categories.map((category) => [category.id, category]))
  const totals = new Map<string, number>()
  for (const record of records) {
    if (record.type !== type) continue
    const category = byId.get(record.categoryId)
    if (!category?.parentId) continue
    totals.set(category.parentId, (totals.get(category.parentId) ?? 0) + record.amountCents)
  }
  const total = [...totals.values()].reduce((sum, value) => sum + value, 0)
  return [...totals.entries()]
    .map(([parentId, amountCents]) => {
      const parent = byId.get(parentId)
      return {
        categoryId: parentId,
        name: parent?.name ?? '未分类',
        icon: parent?.icon ?? '❓',
        amountCents,
        ratio: total === 0 ? 0 : amountCents / total,
      }
    })
    .sort((a, b) => b.amountCents - a.amountCents)
}

function filterRange(records: readonly TransactionRecord[], range: TransactionRange, reference: Date): TransactionRecord[] {
  const bounds = rangeBounds(range, reference)
  return records.filter((record) => isWithin(record.bookedAt, bounds))
}

function buildContinuousTrend(
  records: readonly TransactionRecord[],
  start: Date,
  endInclusive: Date,
  unit: 'day' | 'month',
): TrendPoint[] {
  const buckets = new Map<string, TransactionRecord[]>()
  const cursor = new Date(start.getFullYear(), start.getMonth(), start.getDate())
  const end = new Date(endInclusive.getFullYear(), endInclusive.getMonth(), endInclusive.getDate())

  while (cursor <= end) {
    const key = unit === 'day'
      ? localDateKey(cursor)
      : `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, '0')}`
    buckets.set(key, [])
    if (unit === 'day') cursor.setDate(cursor.getDate() + 1)
    else cursor.setMonth(cursor.getMonth() + 1, 1)
  }

  for (const record of records) {
    const recordDate = new Date(record.bookedAt)
    const key = unit === 'day'
      ? localDateKey(recordDate)
      : `${recordDate.getFullYear()}-${String(recordDate.getMonth() + 1).padStart(2, '0')}`
    buckets.get(key)?.push(record)
  }

  return [...buckets.entries()].map(([key, values]) => ({
    key,
    label: unit === 'day' ? key.slice(5).replace('-', '.') : `${Number(key.slice(5))}月`,
    ...summarize(values),
  }))
}

export function buildDashboard(records: readonly TransactionRecord[], categories: readonly Category[], reference = new Date()): DashboardStats {
  const dayRecords = filterRange(records, 'day', reference)
  const monthRecords = filterRange(records, 'month', reference)
  const yearRecords = filterRange(records, 'year', reference)
  const monthStart = new Date(reference.getFullYear(), reference.getMonth(), 1)
  return {
    day: summarize(dayRecords),
    month: summarize(monthRecords),
    year: summarize(yearRecords),
    monthDailyTrend: buildContinuousTrend(monthRecords, monthStart, reference, 'day'),
    monthExpenseCategories: categoryTotals(monthRecords, categories, 'expense'),
  }
}

export function buildReport(
  records: readonly TransactionRecord[],
  categories: readonly Category[],
  period: 'month' | 'year',
  reference = new Date(),
  now = new Date(),
): ReportStats {
  const filtered = filterRange(records, period, reference)
  const trendStart = period === 'month'
    ? new Date(reference.getFullYear(), reference.getMonth(), 1)
    : new Date(reference.getFullYear(), 0, 1)
  const isCurrentPeriod = period === 'month'
    ? reference.getFullYear() === now.getFullYear() && reference.getMonth() === now.getMonth()
    : reference.getFullYear() === now.getFullYear()
  const trendEnd = isCurrentPeriod
    ? now
    : period === 'month'
      ? new Date(reference.getFullYear(), reference.getMonth() + 1, 0)
      : new Date(reference.getFullYear(), 11, 31)
  return {
    ...summarize(filtered),
    trend: buildContinuousTrend(filtered, trendStart, trendEnd, period === 'month' ? 'day' : 'month'),
    incomeCategories: categoryTotals(filtered, categories, 'income'),
    expenseCategories: categoryTotals(filtered, categories, 'expense'),
  }
}


export function groupTransactions(records: readonly TransactionRecord[], range: TransactionRange): Map<string, TransactionRecord[]> {
  const result = new Map<string, TransactionRecord[]>()
  for (const record of [...records].sort((a, b) => b.bookedAt.localeCompare(a.bookedAt))) {
    const key = groupStartOf(range, record.bookedAt)
    const items = result.get(key) ?? []
    items.push(record)
    result.set(key, items)
  }
  return result
}

export function todayIsoInput(reference = new Date()): string {
  return localDateKey(reference)
}
