export type TransactionRange = 'day' | 'week' | 'month' | 'year'

const WEEKDAY_LABELS = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'] as const

export function localDateKey(value: Date | string): string {
  const date = typeof value === 'string' ? new Date(value) : value
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

export function startOfDay(value: Date | string): Date {
  const date = typeof value === 'string' ? new Date(value) : value
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function startOfIsoWeek(value: Date | string): Date {
  const date = startOfDay(value)
  const offset = (date.getDay() + 6) % 7
  date.setDate(date.getDate() - offset)
  return date
}

export function isoWeek(value: Date | string): { year: number; week: number } {
  const date = startOfDay(value)
  date.setDate(date.getDate() + 3 - ((date.getDay() + 6) % 7))
  const isoYear = date.getFullYear()
  const weekOne = new Date(isoYear, 0, 4)
  const weekOneThursday = new Date(weekOne)
  weekOneThursday.setDate(weekOne.getDate() + 3 - ((weekOne.getDay() + 6) % 7))
  const week = 1 + Math.round((date.getTime() - weekOneThursday.getTime()) / 604_800_000)
  return { year: isoYear, week }
}

export function groupStartOf(range: TransactionRange, value: Date | string): string {
  const date = startOfDay(value)
  if (range === 'week') return localDateKey(startOfIsoWeek(date))
  if (range === 'month') return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-01`
  if (range === 'year') return `${date.getFullYear()}-01-01`
  return localDateKey(date)
}

export function groupTitleOf(range: TransactionRange, key: string): string {
  const date = new Date(`${key}T00:00:00`)
  if (range === 'day') return `${date.getDate()}日`
  if (range === 'week') {
    const value = isoWeek(date)
    return `第${value.week}周`
  }
  if (range === 'month') return `${date.getMonth() + 1}月`
  return `${date.getFullYear()}年`
}

export function groupTitleSubtitleOf(range: TransactionRange, key: string): string | undefined {
  if (range !== 'day') return undefined
  const date = new Date(`${key}T00:00:00`)
  return `${date.getFullYear()}.${date.getMonth() + 1}`
}

export function dayGroupTitle(parentRange: TransactionRange, value: Date | string): string {
  const date = startOfDay(value)
  const prefix = parentRange === 'year' ? `${date.getMonth() + 1}月` : ''
  return `${prefix}${date.getDate()}日 ${WEEKDAY_LABELS[date.getDay()]}`
}

export function rangeBounds(range: TransactionRange, reference: Date): { start: Date; endExclusive: Date } {
  const start = range === 'week' ? startOfIsoWeek(reference) : startOfDay(reference)
  if (range === 'month') start.setDate(1)
  if (range === 'year') {
    start.setMonth(0)
    start.setDate(1)
  }
  const endExclusive = new Date(start)
  if (range === 'day') endExclusive.setDate(endExclusive.getDate() + 1)
  if (range === 'week') endExclusive.setDate(endExclusive.getDate() + 7)
  if (range === 'month') endExclusive.setMonth(endExclusive.getMonth() + 1)
  if (range === 'year') endExclusive.setFullYear(endExclusive.getFullYear() + 1)
  return { start, endExclusive }
}

export function isWithin(value: string, bounds: { start: Date; endExclusive: Date }): boolean {
  const time = new Date(value).getTime()
  return time >= bounds.start.getTime() && time < bounds.endExclusive.getTime()
}
